       { id: 3, name: "Wool Blend Throw", price: 120, image: "https://images.unsplash.com/photo-1520406853248-1850ad3c7a8e?auto=format&fit=crop&w=400&h=400&q=80" },
       { id: 4, name: "Bamboo Storage Box", price: 32, image: "https://images.unsplash.com/photo-1591129841117-3adfd313e34f?auto=format&fit=crop&w=400&h=400&q=80" }
     ];

     const deals = [
       { id: 5, name: "Leather Tote Bag", price: 140, originalPrice: 210, image: "https://images.unsplash.com/photo-1544816153-12ad58913c3f?auto=format&fit=crop&w=400&h=400&q=80", badge: "33% OFF" },
       { id: 6, name: "Noise Cancelling Headphones", price: 199, originalPrice: 299, image: "https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=400&h=400&q=80", badge: "SALE" }
     ];

     const ProductCard = ({ product }) => `
       <li class="product-card">
         <img src="${product.image}" alt="${product.name}" loading="lazy">
         <div class="product-info">
           ${product.badge ? \`<span class="badge">\${product.badge}</span>\` : ''}
           <h3 class="product-name">
             <a href="/product/\${product.id}">\${product.name}</a>
           </h3>
           <p class="product-price">
             $\${product.price}
             \${product.originalPrice ? \`<span class="sr-only">Original price $\${product.originalPrice}</span><small style="text-decoration: line-through; color: #595959; margin-left: 0.5rem; font-weight: normal;">$\${product.originalPrice}</small>\` : ''}
           </p>
           <button type="button" class="add-to-cart" aria-label="Add to cart: \${product.name}">
             Add to cart
           </button>
         </div>
       </li>
     \`;

     const ProductGrid = ({ title, id, products }) => \`
       <section aria-labelledby="\${id}-heading">
         <h2 id="\${id}-heading">\${title}</h2>
         <ul class="product-grid">
           \${products.map(p => ProductCard({ product: p })).join('')}
         </ul>
       </section>
     \`;

     const Hero = () => \`
       <section class="hero" aria-label="Editorial Highlight">
         <h1>Summer Essentials</h1>
         <p>Discover our curated collection of sustainably sourced products designed for modern living.</p>
         <a href="/collections/summer" class="cta-button">Shop the Collection</a>
       </section>
     \`;

     const App = () => \`
       \${Hero()}
       \${ProductGrid({ title: "Featured Products", id: "featured", products: featuredProducts })}
       \${ProductGrid({ title: "Today's Deals", id: "deals", products: deals })}
     \`;

     const render = () => {
       const root = document.getElementById('app');
       if (root) {
         root.innerHTML = App();
       }
     };

     render();
   </script>
 </body>
 </html>

')
